<?php
declare(strict_types=1);

if ($section === 'simulation-toggle') {
    $id=(int)($_POST['id']??0);$s=db()->prepare('UPDATE careers SET simulation_enabled=CASE WHEN simulation_enabled=1 THEN 0 ELSE 1 END WHERE id=?');$s->execute([$id]);audit('Đổi trạng thái mô phỏng','career',$id);flash('success','Đã cập nhật trạng thái mô phỏng.');redirect('admin.php?section=simulations');
}
$total=(int)db()->query('SELECT COUNT(*) FROM simulation_attempts')->fetchColumn();
$students=(int)db()->query('SELECT COUNT(DISTINCT user_id) FROM simulation_attempts')->fetchColumn();
$average=(int)round((float)db()->query('SELECT COALESCE(AVG(score),0) FROM simulation_attempts')->fetchColumn());
$jobs=db()->query('SELECT c.*,COUNT(sa.id) attempt_count,COALESCE(ROUND(AVG(sa.score)),0) average_score FROM careers c LEFT JOIN simulation_attempts sa ON sa.career_id=c.id GROUP BY c.id ORDER BY attempt_count DESC,c.title')->fetchAll();
$recent=db()->query('SELECT sa.*,u.name,u.email,c.title,c.icon FROM simulation_attempts sa JOIN users u ON u.id=sa.user_id JOIN careers c ON c.id=sa.career_id ORDER BY sa.completed_at DESC LIMIT 100')->fetchAll();
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Quản lý mô phỏng · Admin</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="<?=url('assets/css/app.css')?>"><link rel="stylesheet" href="<?=url('assets/css/admin.css')?>"></head><body><div class="admin-layout"><aside class="sidebar"><a class="brand" href="<?=url('admin.php')?>"><span>✦</span>Admin 360</a><nav><?php foreach(['dashboard'=>'▦ Tổng quan','careers'=>'💼 Nghề nghiệp','simulations'=>'🎮 Mô phỏng nghề','questions'=>'☑ Câu hỏi','users'=>'👥 Học sinh','results'=>'📈 Kết quả','settings'=>'⚙ Cấu hình'] as $k=>$v):?><a class="<?=$section===$k?'active':''?>" href="<?=url('admin.php?section='.$k)?>"><?=$v?></a><?php endforeach;?><a href="<?=url('index.php')?>">← Xem website</a></nav></aside><main class="admin-main"><header class="admin-top"><div><span class="muted">Hệ thống quản trị</span><h1>Quản lý mô phỏng nghề</h1></div><div class="user-chip"><span class="avatar" style="background:<?=e(user()['avatar_color'])?>"><?=e(mb_substr(user()['name'],0,1))?></span><b><?=e(user()['name'])?></b></div></header><?php foreach(pull_flashes() as $f):?><div class="alert alert-<?=e($f['type'])?>"><?=e($f['message'])?></div><?php endforeach;?>
<div class="admin-stats"><div class="card"><span class="muted">Tổng lượt chơi</span><strong><?=number_format($total)?></strong></div><div class="card"><span class="muted">Học sinh trải nghiệm</span><strong><?=number_format($students)?></strong></div><div class="card"><span class="muted">Điểm trung bình</span><strong><?=$average?>%</strong></div><div class="card"><span class="muted">Game đang bật</span><strong><?=count(array_filter($jobs,fn($x)=>(int)($x['simulation_enabled']??1)===1))?>/15</strong></div></div>
<div class="toolbar"><span class="muted">Bật/tắt game nội bộ; link tài nguyên ngoài vẫn sửa tại mục Nghề nghiệp.</span><a class="btn btn-primary" target="_blank" href="<?=url('index.php?page=simulations')?>">Mở phòng mô phỏng ↗</a></div><div class="card table-wrap"><table><thead><tr><th>Game nghề nghiệp</th><th>Tình huống</th><th>Lượt chơi</th><th>Điểm TB</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($jobs as $x):$game=simulation_catalog()[$x['slug']]??null;if(!$game)continue;?><tr><td><b><?=e($x['icon'].' '.$game['title'])?></b><br><small class="muted"><?=e($game['role'])?></small></td><td><?=count($game['missions'])?> nhiệm vụ</td><td><?=$x['attempt_count']?></td><td><?=$x['average_score']?>%</td><td><span class="status status-<?=($x['simulation_enabled']??1)?'on':'off'?>"><?=($x['simulation_enabled']??1)?'Đang bật':'Tạm ẩn'?></span></td><td><form method="post" action="<?=url('admin.php?section=simulation-toggle')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn <?=($x['simulation_enabled']??1)?'btn-danger':''?>"><?=($x['simulation_enabled']??1)?'Tạm ẩn':'Bật lại'?></button></form></td></tr><?php endforeach;?></tbody></table></div>
<h2 class="mt-8">Lượt chơi gần đây</h2><div class="card table-wrap"><table><thead><tr><th>Học sinh</th><th>Nghề</th><th>Điểm</th><th>Thời lượng</th><th>Hoàn thành</th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="5" class="empty">Chưa có lượt chơi nào.</td></tr><?php else:foreach($recent as $x):?><tr><td><b><?=e($x['name'])?></b><br><small><?=e($x['email'])?></small></td><td><?=e($x['icon'].' '.$x['title'])?></td><td><b class="text-brand-600"><?=$x['score']?>/100</b></td><td><?=max(1,(int)ceil($x['duration_seconds']/60))?> phút</td><td><?=date('d/m/Y H:i',strtotime($x['completed_at']))?></td></tr><?php endforeach;endif;?></tbody></table></div>
</main></div><script src="<?=url('assets/js/app.js')?>"></script></body></html><?php exit;
